# Tool/resource/prompt logic is defined once, independent of transport
@server.tool()
def search_docs(query: str) -> list:
    return db.search(query)

# Which transport carries the JSON-RPC messages is a deployment choice,
# made at startup -- the tool definition above doesn't change either way.
if deployment == "local_single_host":
    server.run(transport="stdio")
else:
    server.run(transport="http", host="0.0.0.0", port=8080, auth=require_auth)
